/**
 * @file macho.c
 * @brief 32-bit Mach-O loader (MH_EXECUTE, ARMv6 / ARMv7) for PlayStation Vita.
 * @details
 * 1. __TEXT is assembled in temporary memory, relocated/rebased, and copied to an RX block via kubridge;
 *    __DATA is mapped to a contiguous RW block at fixed virtual offset MACHO_SLIDE.
 * 2. rebase.bin (generated by tools/macho_prep.py) lists absolute __DATA/__TEXT pointers to relocate.
 * 3. Imports: resolves dynamic imports intercepting calls to iOS / Darwin / UIKit libraries.
 *    Any unresolved symbol routes to an automatic logging thunk or zeroed data block.
 */
#include <kubridge.h>
#include <psp2/kernel/sysmem.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "imports.h"
#include "log.h"
#include "macho.h"

#define LC_SEGMENT 0x1
#define LC_SYMTAB 0x2
#define LC_DYSYMTAB 0xB
#define LC_ENCRYPTION_INFO 0x21

#define S_ZEROFILL 0x1
#define S_NON_LAZY_SYMBOL_POINTERS 0x6
#define S_LAZY_SYMBOL_POINTERS 0x7

#define INDIRECT_SYMBOL_LOCAL 0x80000000u
#define INDIRECT_SYMBOL_ABS 0x40000000u

#define N_STAB 0xE0
#define N_TYPE 0x0E
#define N_SECT 0x0E
#define N_ARM_THUMB_DEF 0x0008

#ifndef SCE_KERNEL_MEMBLOCK_TYPE_USER_RX
#define SCE_KERNEL_MEMBLOCK_TYPE_USER_RX 0x0C20D050
#endif

#ifndef SCE_KERNEL_MEMBLOCK_TYPE_USER_RW
#define SCE_KERNEL_MEMBLOCK_TYPE_USER_RW 0x0C20D060
#endif

#define ALIGN(x, a) (((x) + (a)-1) & ~((a)-1))
#define THUNK_ARENA_SIZE 0x20000

typedef struct {
    uint32_t cmd, cmdsize;
    char segname[16];
    uint32_t vmaddr, vmsize, fileoff, filesize, maxprot, initprot, nsects, flags;
} segment_command;

typedef struct {
    char sectname[16], segname[16];
    uint32_t addr, size, offset, align, reloff, nreloc, flags, reserved1, reserved2;
} section;

typedef struct {
    uint32_t n_strx;
    uint8_t n_type, n_sect;
    uint16_t n_desc;
    uint32_t n_value;
} nlist;

typedef struct {
    uint32_t ilocalsym, nlocalsym, iextdefsym, nextdefsym, iundefsym, nundefsym, tocoff, ntoc,
        modtaboff, nmodtab, extrefsymoff, nextrefsyms, indirectsymoff, nindirectsyms, extreloff,
        nextrel, locreloff, nlocrel;
} dysymtab_command;

static uint8_t *file_data;
static uint32_t file_slice_offset = 0;
static nlist *symtab;
static uint32_t nsyms;
static const char *strtab;
static uint32_t text_vm, text_size, data_vm, data_size;
static uint8_t *text_buf;
static uintptr_t text_real;
static uint32_t mod_init_addr, mod_init_count;

static uint32_t *thunk_head, *thunk_end;
static const char **unimpl_names;
static int unimpl_count;

extern void ml_unimpl_entry(void);
extern void ml_align_call(void);

void ml_unimpl_log(int idx) {
    static uint8_t seen[4096];
    if (idx < (int)sizeof(seen) && seen[idx] < 3) {
        seen[idx]++;
        l_warn("unimpl import: %s%s", unimpl_names[idx], seen[idx] == 3 ? " (silenced)" : "");
    }
}

static uintptr_t make_thunk(uint32_t ip_value, void *jump) {
    if (thunk_head + 4 > thunk_end)
        fatal_error("Thunk arena exhausted");
    uint32_t code[4] = {
        0xE59FC000, // ldr ip, [pc, #0]
        0xE59FF000, // ldr pc, [pc, #0]
        ip_value,
        (uint32_t)jump,
    };
    uintptr_t addr = (uintptr_t)thunk_head;
    kuKernelCpuUnrestrictedMemcpy(thunk_head, code, sizeof(code));
    kuKernelFlushCaches(thunk_head, sizeof(code));
    thunk_head += 4;
    return addr;
}

static uintptr_t make_unimpl_thunk(const char *name) {
    unimpl_names = realloc(unimpl_names, (unimpl_count + 1) * sizeof(char *));
    unimpl_names[unimpl_count] = name;
    return make_thunk(unimpl_count++, ml_unimpl_entry);
}

static uintptr_t make_unimpl_data(const char *name) {
    static struct {
        const char *name;
        uintptr_t addr;
    } blocks[512];
    static int nblocks;
    for (int i = 0; i < nblocks; i++)
        if (!strcmp(blocks[i].name, name))
            return blocks[i].addr;
    void *b = calloc(1, 256);
    if (nblocks < 512)
        blocks[nblocks++] = (typeof(blocks[0])){name, (uintptr_t)b};
    return (uintptr_t)b;
}

static uint32_t *word_ptr(uint32_t vmaddr) {
    if (vmaddr >= text_vm && vmaddr + 4 <= text_vm + text_size)
        return (uint32_t *)(text_buf + (vmaddr - text_vm));
    if (vmaddr >= data_vm && vmaddr + 4 <= data_vm + data_size)
        return (uint32_t *)(data_vm + MACHO_SLIDE + (vmaddr - data_vm));
    return NULL;
}

static uintptr_t resolve_sym(uint32_t sym_idx, int is_lazy) {
    if (sym_idx >= nsyms)
        return 0;
    nlist *s = &symtab[sym_idx];
    if (!(s->n_type & N_STAB) && (s->n_type & N_TYPE) == N_SECT) {
        uintptr_t a = MACHO_SLIDE + s->n_value;
        if (s->n_desc & N_ARM_THUMB_DEF)
            a |= 1;
        return a;
    }
    const char *name = strtab + s->n_strx;
    const import_entry *e = imports_lookup(name);
    if (e)
        return e->data ? e->addr : make_thunk(e->addr, ml_align_call);
    return is_lazy ? make_unimpl_thunk(name) : make_unimpl_data(name);
}

static int alloc_block(const char *name, SceKernelMemBlockType type, uintptr_t addr, uint32_t size) {
    SceKernelAllocMemBlockKernelOpt opt;
    memset(&opt, 0, sizeof(opt));
    opt.size = sizeof(opt);
    opt.attr = 0x1;
    opt.field_C = addr;
    SceUID id = kuKernelAllocMemBlock(name, type, size, &opt);
    if (id < 0) {
        l_error("kuKernelAllocMemBlock(%s, 0x%08X, size 0x%X) failed: 0x%08X", name, (unsigned)addr, (unsigned)size, (unsigned)id);
        return id;
    }
    void *base = NULL;
    sceKernelGetMemBlockBase(id, &base);
    if ((uintptr_t)base != addr)
        fatal_error("%s allocated at %p instead of required 0x%08X", name, base, (unsigned)addr);
    return 0;
}

uintptr_t macho_sym(const char *name) {
    if (!symtab || !strtab)
        return 0;
    const char *alt_name = (name[0] == '_') ? (name + 1) : NULL;
    for (uint32_t i = 0; i < nsyms; i++) {
        nlist *s = &symtab[i];
        if (s->n_type & N_STAB)
            continue;
        if ((s->n_type & N_TYPE) != N_SECT)
            continue;
        const char *sn = strtab + s->n_strx;
        if (!strcmp(sn, name) || (alt_name && !strcmp(sn, alt_name))) {
            uintptr_t a = MACHO_SLIDE + s->n_value;
            if (s->n_desc & N_ARM_THUMB_DEF)
                a |= 1;
            return a;
        }
    }
    return 0;
}

void macho_hook(const char *name, void *dst) {
    uintptr_t a = macho_sym(name);
    if (!a) {
        l_warn("macho_hook: symbol '%s' not found", name);
        return;
    }
    uint32_t code[4] = {
        0xE59FC000, // ldr ip, [pc, #0]
        0xE59FF000, // ldr pc, [pc, #0]
        (uint32_t)dst,
        (uint32_t)dst,
    };
    kuKernelCpuUnrestrictedMemcpy((void *)(a & ~1), code, sizeof(code));
    kuKernelFlushCaches((void *)(a & ~1), sizeof(code));
}

static void macho_patch_vfp_vectors(uint8_t *text, uint32_t text_sz, uint32_t text_vm) {
    // Pattern mappings: VFP vector instruction -> NEON SIMD instruction
    // On ARMv7 Cortex-A9 (PS Vita), VFP vector mode (FPSCR.LEN != 0) is deprecated
    // and unsupported in hardware, triggering Undefined instruction exception 0x30002.
    // In HOS2 (compiled for ARMv6 VFPv2), 4x4 matrix and vector transformations use
    // FPSCR.LEN=3 (length 4) and LEN=2 (length 3). All 73 vector blocks in HOS2 map
    // 1:1 to standard ARM NEON SIMD instructions operating on q6/q7 and q2-q5.
    static const struct {
        uint32_t vfp;
        uint32_t neon;
    } k_vfp_neon[] = {
        { 0xee24ca00, 0xf3a4c940 }, // vmul.f32 q6, q2, d0[0]
        { 0xee06ca20, 0xf3a6c160 }, // vmla.f32 q6, q3, d0[1]
        { 0xee08ca01, 0xf3a8c141 }, // vmla.f32 q6, q4, d1[0]
        { 0xee0aca21, 0xf3aac161 }, // vmla.f32 q6, q5, d1[1]
        { 0xee24ea02, 0xf3a4e942 }, // vmul.f32 q7, q2, d2[0]
        { 0xee06ea22, 0xf3a6e162 }, // vmla.f32 q7, q3, d2[1]
        { 0xee08ea03, 0xf3a8e143 }, // vmla.f32 q7, q4, d3[0]
        { 0xee0aea23, 0xf3aae163 }, // vmla.f32 q7, q5, d3[1]
        { 0xee3cca0a, 0xf20ccd4a }, // vadd.f32 q6, q6, q5
    };
    const uint32_t NOP_INSTR = 0xe1a00000; // nop (mov r0, r0)

    uint32_t *words = (uint32_t *)text;
    uint32_t nwords = text_sz / 4;

    uint32_t blocks_patched = 0;
    uint32_t instrs_patched = 0;

    for (uint32_t i = 3; i < nwords - 4; i++) {
        uint32_t w = words[i];
        if ((w & 0x0fff0fff) != 0x0ee10a10)
            continue; // Not a vmsr fpscr, rX

        // Check if preceding instruction is: orr r0, r0, #0x20000 or #0x30000 (entering vector mode)
        uint32_t w_prev = words[i - 1];
        if ((w_prev & 0x0fef0000) != 0x03800000)
            continue; // Not an enter sequence

        uint32_t enter_idx = i;

        // Find paired exit vmsr fpscr, rX
        uint32_t exit_idx = 0;
        for (uint32_t j = enter_idx + 1; j < nwords && j < enter_idx + 64; j++) {
            if ((words[j] & 0x0fff0fff) == 0x0ee10a10) {
                exit_idx = j;
                break;
            }
        }

        if (!exit_idx)
            continue;

        // NOP out the enter sequence (vmrs, bic, orr, vmsr: 4 words)
        for (uint32_t p = enter_idx - 3; p <= enter_idx; p++) {
            words[p] = NOP_INSTR;
            instrs_patched++;
        }

        // Find the exit vmrs r0, fpscr (0xeef10a10) before exit_idx
        uint32_t exit_vmrs_idx = exit_idx - 2;
        for (uint32_t p = exit_idx - 1; p >= enter_idx && p >= exit_idx - 5; p--) {
            if (words[p] == 0xeef10a10) {
                exit_vmrs_idx = p;
                break;
            }
        }

        // NOP out the exit sequence (from vmrs to exit vmsr)
        for (uint32_t p = exit_vmrs_idx; p <= exit_idx; p++) {
            words[p] = NOP_INSTR;
            instrs_patched++;
        }

        // Translate VFP vector math instructions inside body to NEON SIMD
        for (uint32_t p = enter_idx + 1; p < exit_vmrs_idx; p++) {
            uint32_t inst = words[p];
            for (size_t k = 0; k < sizeof(k_vfp_neon) / sizeof(k_vfp_neon[0]); k++) {
                if (inst == k_vfp_neon[k].vfp) {
                    words[p] = k_vfp_neon[k].neon;
                    instrs_patched++;
                    break;
                }
            }
        }

        blocks_patched++;
        i = exit_idx; // Advance past this block
    }

    if (blocks_patched > 0) {
        l_info("Patched %u VFPv2 vector blocks (%u instructions) -> ARM NEON SIMD.",
               (unsigned)blocks_patched, (unsigned)instrs_patched);
    } else {
        l_info("VFPv2 vector scan: 0 vector blocks found (already patched or none).");
    }
}

static void apply_rebase(const char *rebase_path) {
    FILE *f = fopen(rebase_path, "rb");
    if (!f) {
        l_warn("Not found %s: skipping offline rebase", rebase_path);
        return;
    }
    uint32_t rh[2] = {0};
    if (fread(rh, 4, 2, f) != 2 || rh[0] != 0x31534252 /* RBS1 */) {
        fclose(f);
        l_error("Invalid rebase.bin header format (expected RBS1)");
        return;
    }
    uint32_t count = rh[1];
    uint32_t *entries = malloc(count * sizeof(uint32_t));
    if (!entries) {
        fclose(f);
        return;
    }
    fread(entries, sizeof(uint32_t), count, f);
    fclose(f);

    l_info("Applying %u rebase words from %s...", (unsigned)count, rebase_path);
    int applied = 0;
    for (uint32_t i = 0; i < count; i++) {
        uint32_t *w = word_ptr(entries[i]);
        if (w) {
            *w += MACHO_SLIDE;
            applied++;
        }
    }
    free(entries);
    l_info("Rebase complete: %d words relocated.", applied);
}

int macho_load(const char *bin_path, const char *rebase_path) {
    l_info("Loading Mach-O executable: %s", bin_path);
    FILE *f = fopen(bin_path, "rb");
    if (!f)
        fatal_error("Failed to open %s", bin_path);
    fseek(f, 0, SEEK_END);
    size_t file_len = ftell(f);
    fseek(f, 0, SEEK_SET);

    uint8_t *raw = malloc(file_len);
    if (!raw)
        fatal_error("Insufficient memory to load %s", bin_path);
    fread(raw, 1, file_len, f);
    fclose(f);

    uint8_t *d = raw;
    file_slice_offset = 0;

    // Detect FAT universal Mach-O (big-endian 0xCAFEBABE)
    if (file_len >= 8 && (memcmp(raw, "\xca\xfe\xba\xbe", 4) == 0 || memcmp(raw, "\xbe\xba\xfe\xca", 4) == 0)) {
        uint32_t nfat = (raw[4] << 24) | (raw[5] << 16) | (raw[6] << 8) | raw[7];
        uint32_t chosen_offset = 0, chosen_size = 0;
        const char *arch_name = "arm";
        for (uint32_t i = 0; i < nfat; i++) {
            const uint8_t *arch_ptr = raw + 8 + i * 20;
            uint32_t cputype = (arch_ptr[0] << 24) | (arch_ptr[1] << 16) | (arch_ptr[2] << 8) | arch_ptr[3];
            uint32_t cpusub = (arch_ptr[4] << 24) | (arch_ptr[5] << 16) | (arch_ptr[6] << 8) | arch_ptr[7];
            uint32_t off = (arch_ptr[8] << 24) | (arch_ptr[9] << 16) | (arch_ptr[10] << 8) | arch_ptr[11];
            uint32_t sz = (arch_ptr[12] << 24) | (arch_ptr[13] << 16) | (arch_ptr[14] << 8) | arch_ptr[15];
            if (cputype == 12 /* CPU_TYPE_ARM */) {
                if (cpusub == 9 /* v7 */ || cpusub == 11 /* v7s */) {
                    chosen_offset = off;
                    chosen_size = sz;
                    arch_name = "armv7";
                    break;
                } else if (cpusub == 6 /* v6 */ && !chosen_offset) {
                    chosen_offset = off;
                    chosen_size = sz;
                    arch_name = "armv6";
                }
            }
        }
        if (chosen_offset && chosen_offset + chosen_size <= file_len) {
            l_info("FAT binary detected: selected slice %s (offset 0x%X, size %u KB)",
                   arch_name, (unsigned)chosen_offset, (unsigned)(chosen_size / 1024));
            d = raw + chosen_offset;
            file_slice_offset = chosen_offset;
        }
    }

    file_data = d;
    uint32_t magic = *(uint32_t *)d;
    if (magic != 0xFEEDFACE)
        fatal_error("Invalid Mach-O magic header (0x%08X != 0xFEEDFACE)", (unsigned)magic);

    uint32_t ncmds = *(uint32_t *)(d + 16);
    uint32_t off = 28;

    dysymtab_command *dysym = NULL;
    segment_command *seg_text = NULL, *seg_data = NULL;
    section *sects[64];
    int nsects_total = 0;

    for (uint32_t c = 0; c < ncmds; c++) {
        uint32_t cmd = *(uint32_t *)(d + off);
        uint32_t size = *(uint32_t *)(d + off + 4);
        if (cmd == LC_SEGMENT) {
            segment_command *s = (segment_command *)(d + off);
            if (!strncmp(s->segname, "__TEXT", 16))
                seg_text = s;
            else if (!strncmp(s->segname, "__DATA", 16))
                seg_data = s;
            section *sec = (section *)(s + 1);
            for (uint32_t i = 0; i < s->nsects && nsects_total < 64; i++)
                sects[nsects_total++] = &sec[i];
        } else if (cmd == LC_SYMTAB) {
            uint32_t *p = (uint32_t *)(d + off + 8);
            symtab = (nlist *)(d + p[0]);
            nsyms = p[1];
            strtab = (const char *)(d + p[2]);
        } else if (cmd == LC_DYSYMTAB) {
            dysym = (dysymtab_command *)(d + off + 8);
        } else if (cmd == LC_ENCRYPTION_INFO) {
            uint32_t cryptid = *(uint32_t *)(d + off + 16);
            if (cryptid != 0) {
                l_error("================================================================");
                l_error("CRITICAL ALERT: Binary contains FairPlay DRM encryption (cryptid %u)!", (unsigned)cryptid);
                l_error("Cannot execute encrypted binary on PS Vita. Must be decrypted first.");
                l_error("================================================================");
            }
        }
        off += size;
    }

    if (!seg_text || !seg_data || !symtab || !dysym)
        fatal_error("Mach-O does not contain required __TEXT, __DATA, LC_SYMTAB or LC_DYSYMTAB");

    text_vm = seg_text->vmaddr;
    text_size = seg_text->vmsize;
    data_vm = seg_data->vmaddr;
    data_size = seg_data->vmsize;
    text_real = text_vm + MACHO_SLIDE;

    l_info("Mach-O: __TEXT 0x%08X (size 0x%08X) -> real 0x%08X",
           (unsigned)text_vm, (unsigned)text_size, (unsigned)text_real);
    l_info("Mach-O: __DATA 0x%08X (size 0x%08X) -> real 0x%08X",
           (unsigned)data_vm, (unsigned)data_size, (unsigned)(MACHO_SLIDE + data_vm));

    if (alloc_block("ml_thunks", SCE_KERNEL_MEMBLOCK_TYPE_USER_RX, text_real - THUNK_ARENA_SIZE, THUNK_ARENA_SIZE) < 0 ||
        alloc_block("ml_text", SCE_KERNEL_MEMBLOCK_TYPE_USER_RX, text_real, ALIGN(text_size, 0x1000)) < 0 ||
        alloc_block("ml_data", SCE_KERNEL_MEMBLOCK_TYPE_USER_RW, data_vm + MACHO_SLIDE, ALIGN(data_size, 0x1000)) < 0) {
        fatal_error("kuKernelAllocMemBlock failed! Make sure kubridge.skprx is installed in ur0:tai/config.txt");
    }

    thunk_head = (uint32_t *)(text_real - THUNK_ARENA_SIZE);
    thunk_end = (uint32_t *)text_real;

    text_buf = calloc(1, ALIGN(text_size, 0x1000));
    memcpy(text_buf, d + seg_text->fileoff, seg_text->filesize);

    uint8_t *data_real = (uint8_t *)(data_vm + MACHO_SLIDE);
    memset(data_real, 0, ALIGN(data_size, 0x1000));
    memcpy(data_real, d + seg_data->fileoff, seg_data->filesize);

    // Track special sections like __mod_init_func
    for (int i = 0; i < nsects_total; i++) {
        section *s = sects[i];
        if (!strncmp(s->sectname, "__mod_init_func", 16)) {
            mod_init_addr = s->addr;
            mod_init_count = s->size / 4;
        }
    }

    // Resolve indirect symbols (__nl_symbol_ptr and __la_symbol_ptr)
    uint32_t *indirect = (uint32_t *)(d + dysym->indirectsymoff);
    int n_imports = 0;
    for (int s_idx = 0; s_idx < nsects_total; s_idx++) {
        section *s = sects[s_idx];
        uint32_t type = s->flags & 0xFF;
        if (type != S_NON_LAZY_SYMBOL_POINTERS && type != S_LAZY_SYMBOL_POINTERS)
            continue;
        uint32_t nslots = s->size / 4;
        for (uint32_t i = 0; i < nslots; i++) {
            uint32_t sym_idx = indirect[s->reserved1 + i];
            if (sym_idx & (INDIRECT_SYMBOL_LOCAL | INDIRECT_SYMBOL_ABS))
                continue; // Local symbols handled by rebase
            uint32_t *w = word_ptr(s->addr + i * 4);
            if (w) {
                *w = resolve_sym(sym_idx, type == S_LAZY_SYMBOL_POINTERS);
                n_imports++;
            }
        }
    }

    // Apply external relocations (GENERIC_RELOC_VANILLA)
    if (dysym->nextrel > 0) {
        uint32_t *rel = (uint32_t *)(d + dysym->extreloff);
        for (uint32_t i = 0; i < dysym->nextrel; i++) {
            uint32_t addr = rel[i * 2], info = rel[i * 2 + 1];
            uint32_t *w = word_ptr(addr);
            if (!w || ((info >> 28) & 0xF) != 0 || ((info >> 25) & 3) != 2) {
                l_warn("Unsupported external reloc at 0x%08X (info 0x%08X)", (unsigned)addr, (unsigned)info);
                continue;
            }
            uint32_t sym_idx = info & 0xFFFFFF;
            *w += resolve_sym(sym_idx, 0);
            n_imports++;
        }
    }
    l_info("Resolved %d dynamic imports / relocations (%d unimplemented).", n_imports, unimpl_count);

    // Apply offline rebase relocations
    if (rebase_path)
        apply_rebase(rebase_path);

    // Patch ARMv6 VFPv2 vector mode blocks -> ARM NEON SIMD
    macho_patch_vfp_vectors(text_buf, text_size, text_vm);

    // Copy final __TEXT to executable memory block
    kuKernelCpuUnrestrictedMemcpy((void *)text_real, text_buf, ALIGN(text_size, 0x1000));
    kuKernelFlushCaches((void *)text_real, ALIGN(text_size, 0x1000));
    free(text_buf);
    text_buf = NULL;

    l_info("Mach-O loaded successfully at 0x%08X.", (unsigned)text_real);
    return 0;
}

void macho_run_inits(void) {
    if (!mod_init_addr || !mod_init_count)
        return;
    l_info("Executing %u global constructors (__mod_init_func)...", (unsigned)mod_init_count);
    uint32_t *funcs = (uint32_t *)(mod_init_addr + MACHO_SLIDE);
    for (uint32_t i = 0; i < mod_init_count; i++) {
        uintptr_t fn = funcs[i];
        if (fn) {
            if (fn < MACHO_SLIDE)
                fn += MACHO_SLIDE;
            l_debug("mod_init[%u] = 0x%08X", (unsigned)i, (unsigned)(fn - MACHO_SLIDE));
            call_guest((void *)fn, 0, 0, 0, 0);
        }
    }
    l_info("All %u global constructors completed.", (unsigned)mod_init_count);
}
